<main class="flex-grow-1 p-3"><section class="bg-white rounded p-4 mb-4"><h1 class="h4">Reportar incidencia</h1><form action="procesarAltaIncidencia.php" method="post" class="row g-3">
<div class="col-md-6"><label class="form-label" for="fechaApertura">Fecha de apertura</label><input class="form-control" type="datetime-local" id="fechaApertura" name="fechaApertura" required></div>
