<div class="col-md-6"><label class="form-label" for="nombreDocente">Docente</label><input class="form-control" id="nombreDocente" name="nombreDocente" required></div><div class="col-md-6"><label class="form-label" for="grupo">Grupo</label><input class="form-control" id="grupo" name="grupo" required></div>
<div class="col-md-6"><label class="form-label" for="asignatura">Asignatura</label><input class="form-control" id="asignatura" name="asignatura" required></div><div class="col-md-6"><label class="form-label">¿Reportó un alumno?</label><div><label><input type="radio" name="reportoAlumno" value="SI" required> Sí</label> <label><input type="radio" name="reportoAlumno" value="NO"> No</label></div></div>
<div class="col-md-6"><label class="form-label" for="nombreAlumno">Nombre del alumno</label><input class="form-control" id="nombreAlumno" name="nombreAlumno" disabled></div><div class="col-12"><label class="form-label" for="descripcion">Descripción</label><textarea class="form-control" id="descripcion" name="descripcion" required></textarea></div><div class="col-12"><button class="btn btn-primary">Registrar incidencia</button></div></form></section>
<section class="bg-white rounded p-4"><h2 class="h4">Mis incidencias</h2><div class="table-responsive"><table class="table table-bordered"><thead><tr><th>ID</th><th>Apertura</th><th>Grupo</th><th>Descripción</th><th>Estado</th></tr></thead><tbody><?php foreach ($incidencias as $incidencia): ?><tr><td><?= htmlspecialchars($incidencia["idIncidencia"]) ?></td><td><?= htmlspecialchars($incidencia["fechaApertura"]) ?></td><td><?= htmlspecialchars($incidencia["grupo"]) ?></td><td><?= htmlspecialchars($incidencia["descripcion"]) ?></td><td><?= htmlspecialchars($incidencia["estado"]) ?></td></tr><?php endforeach; ?></tbody></table></div></section></main>
<script>document.querySelectorAll('input[name="reportoAlumno"]').forEach(opcion=>opcion.addEventListener("change",()=>{const campo=document.getElementById("nombreAlumno");campo.disabled=opcion.value!=="SI";campo.required=opcion.value==="SI";if(campo.disabled)campo.value="";}));</script></body></html>
